package com.tuckersoft.branchengine.config; import com.tuckersoft.branchengine.security.*; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.authentication.*; import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.http.HttpMethod; @Configuration public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean AuthenticationManager authenticationManager(AuthenticationConfiguration c)throws Exception{return c.getAuthenticationManager();} @Bean SecurityFilterChain chain(HttpSecurity h,JwtFilter f,SecurityErrorHandlers eh)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).exceptionHandling(e->e.authenticationEntryPoint(eh).accessDeniedHandler(eh)).authorizeHttpRequests(a->a.requestMatchers("/api/v1/auth/**").permitAll().requestMatchers(HttpMethod.POST,"/api/v1/nodes").hasRole("ADMIN").requestMatchers(HttpMethod.GET,"/api/v1/users").hasRole("ADMIN").requestMatchers(HttpMethod.PATCH,"/api/v1/users/*/role").hasRole("ADMIN").requestMatchers("/api/v1/**").authenticated().anyRequest().permitAll()).addFilterBefore(f,UsernamePasswordAuthenticationFilter.class).build();} }
